import java.io.*;import java.util.*;
public class Benchmark{
 static final int[] NS={100,1000,10000,100000};static final int R=5;static Random rnd=new Random(42);static PrintWriter out;
 interface Job{long[]run();}
 static long[] avg(Job j){long t=0,m=0;for(int k=0;k<R;k++){long[]x=j.run();t+=x[0];m+=x[1];}return new long[]{t/R,m/R};}
 static int[] values(int n,long seed){Random r=new Random(seed);int[]x=new int[n];for(int i=0;i<n;i++)x[i]=r.nextInt();return x;}
 static DynamicArray<Integer> da(int[]x){DynamicArray<Integer>a=new DynamicArray<>();for(int v:x)a.add(v);a.resetMetrics();return a;}static LinkedList<Integer> ll(int[]x){LinkedList<Integer>l=new LinkedList<>();for(int v:x)l.add(v);l.resetMetrics();return l;}
 public static void main(String[]z)throws Exception{new File("results/tables").mkdirs();w1();w2();w3();w4();}
 static void w1()throws Exception{out=new PrintWriter("results/tables/random_access.csv");out.println("structure,n,avg_ns,accesses");for(int n:NS){int[]base=values(n,42);int[]idx=new int[10000];Random r=new Random(42);for(int i=0;i<idx.length;i++)idx[i]=r.nextInt(n);for(String s:new String[]{"DynamicArray","LinkedList"}){long[]q=avg(()->{Object d=s.equals("DynamicArray")?da(base):ll(base);long st=System.nanoTime();if(d instanceof DynamicArray<?> a)for(int i:idx)a.get(i);else if(d instanceof LinkedList<?> l)for(int i:idx)l.get(i);long tm=System.nanoTime()-st;long m=d instanceof DynamicArray<?> a?a.getAccesses():((LinkedList<?>)d).getAccesses();return new long[]{tm,m};});out.printf("%s,%d,%d,%d%n",s,n,q[0],q[1]);}}out.close();}
 static void w2()throws Exception{out=new PrintWriter("results/tables/search.csv");out.println("structure,n,avg_ns,comparisons");for(int n:NS){int[]base=values(n,42);int[]qs=values(1000,99);for(String s:new String[]{"DynamicArray","LinkedList"}){long[]q=avg(()->{Object d=s.equals("DynamicArray")?da(base):ll(base);long st=System.nanoTime();if(d instanceof DynamicArray<?> a)for(int x:qs)((DynamicArray<Integer>)a).contains(x);else for(int x:qs)((LinkedList<Integer>)d).contains(x);long tm=System.nanoTime()-st;long m=d instanceof DynamicArray<?> a?a.getComparisons():((LinkedList<?>)d).getComparisons();return new long[]{tm,m};});out.printf("%s,%d,%d,%d%n",s,n,q[0],q[1]);}}out.close();}
 static void w3()throws Exception{out=new PrintWriter("results/tables/insert_remove.csv");out.println("structure,operation,position,n,avg_ns,movements_or_accesses");for(int n:NS){int[]base=values(n,42);for(String s:new String[]{"DynamicArray","LinkedList"})for(String op:new String[]{"insert","remove"})for(String pos:new String[]{"beginning","middle"}){long[]q=avg(()->{Object d=s.equals("DynamicArray")?da(base):ll(base);int index=pos.equals("beginning")?0:n/2;long st=System.nanoTime();if(op.equals("insert")){for(int k=0;k<1000;k++){if(d instanceof DynamicArray<?> a)((DynamicArray<Integer>)a).add(index,k);else ((LinkedList<Integer>)d).add(index,k);}}else{for(int k=0;k<Math.min(1000,n);k++){int ri=pos.equals("beginning")?0:(d instanceof DynamicArray<?> a?a.size()/2:((LinkedList<?>)d).size()/2);if(d instanceof DynamicArray<?> a)((DynamicArray<Integer>)a).remove(ri);else ((LinkedList<Integer>)d).remove(ri);}}long tm=System.nanoTime()-st;long m=d instanceof DynamicArray<?> a?a.getMovements():((LinkedList<?>)d).getAccesses();return new long[]{tm,m};});out.printf("%s,%s,%s,%d,%d,%d%n",s,op,pos,n,q[0],q[1]);}}out.close();}
 static void w4()throws Exception{out=new PrintWriter("results/tables/heap.csv");out.println("operation,n,avg_ns,comparisons,sorted");for(int n:NS){int[]base=values(n,42);long ti=0,te=0,ci=0,ce=0;boolean sorted=true;for(int z=0;z<R;z++){MinHeap<Integer>h=new MinHeap<>();long st=System.nanoTime();for(int x:base)h.insert(x);ti+=System.nanoTime()-st;ci+=h.getComparisons();h.resetMetrics();int last=Integer.MIN_VALUE;st=System.nanoTime();while(h.size()>0){int x=h.extractMin();if(x<last)sorted=false;last=x;}te+=System.nanoTime()-st;ce+=h.getComparisons();}out.printf("insert,%d,%d,%d,%s%n",n,ti/R,ci/R,sorted);out.printf("extract,%d,%d,%d,%s%n",n,te/R,ce/R,sorted);}out.close();}
}
